CustomField.formula:
IF(
    TEXT(Type_SMS__c) = 'SMS Interaktif',

    LOWER(
        "i" +
        SUBSTITUTE(Media_Seller__r.prefix_ms__c, "-", "") +
        SUBSTITUTE(newSenderid__c, "+", "")
    ),

    IF(TEXT(Type_Sender__c)='Premium','p','r')

    +

    LOWER(

    IF(

    /* Cek apakah prefixnya mcm atau jts */

    OR(

    Media_Seller__r.prefix_ms__c = 'mcm',

    Media_Seller__r.prefix_ms__c = 'jts'

    ),

    /* Jika ya, tulis dua kali (doubled) */

    Media_Seller__r.prefix_ms__c + Media_Seller__r.prefix_ms__c,



    /* Jika bukan, jalankan logika mustika/normal seperti sebelumnya */

    IF(

    Media_Seller__r.prefix_ms__c != 'mustika',

    SUBSTITUTE(Media_Seller__r.prefix_ms__c, "-", ""),

    IF(TEXT(Karet__c) = 'YES', 'muskrt', 'mustika')

    )

    )

    )

    +

    LOWER(Kategori_Industri__r.prefix_ms__c + SUBSTITUTE(newSenderid__c, "+", ""))
)
